package com.viitube.proxy.proto;

/** Base class of the messages generated by tools/protoc_java.py. */
public abstract class ProtoMessage {
    static final byte[] EMPTY_BYTES = new byte[0];

    public abstract void writeTo(ProtoWriter writer);

    public abstract void mergeFrom(ProtoReader reader) throws java.io.IOException;

    public final byte[] toByteArray() {
        ProtoWriter writer = new ProtoWriter();
        writeTo(writer);
        return writer.toByteArray();
    }
}
